            return [[i % 2] for i in range(n)]
        subcircuits = [random_monotone_circuit(k-1, n//2)]
        for i in range(1, n//2):
            subcircuits.append([i % 2])
        return [subcircuit + [sum(subcircuit) % 2] for subcircuit in subcircuits]

