        if len(circuit) == 1:
            return circuit
        q = {}
        for i in range(len(circuit)):
            for j in range(i+1, len(circuit)):
                if circuit[i][0] != circuit[j][0]:
                    q[(i, j)] = (circuit[i][1] + circuit[j][1]) % 2
        return q

    def minimal_rank(q):
        rank = 0
        for i in range(len(q)):
            for j in range(i+1, len(q)):
                if q[(i, j)] == 0:
                    continue
                found = False
                for k in range(rank):
